-- PC-AC 2026 — deepen the cost accounting and rateio trainer.
-- Keeps every question, answer key and question order. Adds step-by-step
-- solutions and exam tips; removes a misplaced CPC 26 section from this lesson.

update public.study_materials
set body_md=split_part(body_md, E'\n## Classificação dos passivos financeiros — CPC 26', 1),
    updated_at=now()
where contest_name='PC-AC 2026'
  and slug='pcac-2026-contabilidade-08-custos-materia-prima-rateio-departamentalizacao';

with qdata(n,why,tip,steps) as (
 values
 (1,'Consumo é a quantidade de matéria-prima que saiu do estoque para ser usada na produção. Primeiro some o que já existia com as compras: R$ 3.000 + R$ 11.000 = R$ 14.000 disponíveis. Depois retire o que sobrou no fim: R$ 14.000 − R$ 5.000 = R$ 9.000 consumidos.','Macete: EI + Compras − EF. O estoque final sempre é subtraído porque não foi consumido.','["Identifique o estoque inicial: R$ 3.000.","Some as compras: R$ 3.000 + R$ 11.000 = R$ 14.000.","Subtraia o estoque final: R$ 14.000 − R$ 5.000 = R$ 9.000.","Compare o resultado com a afirmação: está correta."]'::jsonb),
 (2,'O departamento ocupa 20 dos 100 m², isto é, 20/100 = 0,20 = 20% da área. Como a energia é rateada pela área, ele recebe a mesma proporção da conta: 20% de R$ 50.000 = R$ 10.000. Isso demonstra a regra do rateio proporcional: a fração da área ocupada deve ser igual à fração do custo atribuída. Se o setor ocupasse metade da área, receberia metade da conta; como ocupa apenas um quinto, recebe um quinto.','Use a base que o enunciado indicar. Área pede m²; empregados pede quantidade de pessoas; depreciação pode usar máquinas.','["Divida a área do setor pela área total: 20 ÷ 100 = 0,20.","Converta para percentual: 0,20 = 20%.","Multiplique o gasto pela participação: 50.000 × 0,20 = R$ 10.000.","Confira se a base usada foi área, como pede o enunciado."]'::jsonb),
 (3,'Propaganda e marketing servem para divulgar e vender o produto, não para transformá-lo. Por isso, são despesas comerciais do período. O custo de fabricação reúne matéria-prima consumida, mão de obra da produção e custos indiretos de fabricação. O fato de a propaganda mencionar o produto não a transforma em custo industrial: sua função é comercializar, e não executar uma etapa de fabricação.','Pergunte: esse gasto foi necessário para fabricar ou para vender/administrar? Marketing normalmente é despesa comercial.','["Identifique a finalidade do gasto: divulgação e venda.","Separe gastos de produção dos gastos comerciais.","Classifique propaganda/marketing como despesa comercial.","Não some essa despesa ao custo industrial."]'::jsonb),
 (4,'A depreciação total de R$ 12.000 é distribuída conforme a quantidade de máquinas. Há 2 + 3 + 5 = 10 máquinas. O departamento com 5 máquinas representa 5/10 = 50% do total; portanto recebe 50% × R$ 12.000 = R$ 6.000. A distribuição proporcional garante que departamentos com mais máquinas absorvam uma parcela maior do desgaste dos equipamentos. A soma das parcelas dos três setores deve fechar exatamente os R$ 12.000 de depreciação.','Quando o critério é número de máquinas, use máquinas do setor ÷ total de máquinas.','["Some as máquinas: 2 + 3 + 5 = 10.","Calcule a participação: 5 ÷ 10 = 50%.","Aplique ao total: 12.000 × 50% = R$ 6.000.","Confira: os três departamentos devem absorver juntos R$ 12.000."]'::jsonb),
 (5,'O estoque final representa a matéria-prima que permaneceu guardada e, portanto, não foi consumida. Por isso, deve ser retirado do total disponível. A fórmula correta é consumo = estoque inicial + compras − estoque final. Exemplo: se havia R$ 14.000 disponíveis e sobraram R$ 5.000, somente R$ 9.000 deixaram o estoque. Somar o saldo final produziria uma quantidade maior do que tudo o que estava disponível para consumo.','Pense no armário: o que havia + o que entrou − o que sobrou = o que saiu para uso.','["Some estoque inicial e compras para encontrar o total disponível.","Retire o estoque que sobrou no fim do período.","Não some o estoque final: isso contaria como consumido algo que continua guardado.","A fórmula é EI + Compras − EF."]'::jsonb),
 (6,'O Departamento de Serviços recebe três parcelas calculadas com bases diferentes: energia por área (R$ 10.000), água/telefone/alimentação por empregados (R$ 20.000) e depreciação por máquinas (R$ 2.400). Somando: R$ 10.000 + R$ 20.000 + R$ 2.400 = R$ 32.400.','Resolva gasto por gasto. Nunca aplique uma única base de rateio a todos os custos se o enunciado indicar critérios diferentes.','["Energia: 20/100 da área × R$ 50.000 = R$ 10.000.","Serviços comuns: 40/200 empregados × R$ 100.000 = R$ 20.000.","Depreciação: 2/10 máquinas × R$ 12.000 = R$ 2.400.","Some as três parcelas: R$ 32.400."]'::jsonb),
 (7,'A energia elétrica é distribuída pela área ocupada, conforme a regra expressa no enunciado. A quantidade de empregados é a base para água, telefone e alimentação. Trocar as bases altera a distribuição e produz resposta errada. A base de rateio deve ser escolhida para cada gasto separadamente, seguindo o que a questão determina. Não basta encontrar uma proporção correta; é necessário aplicá-la ao gasto certo.','Faça uma pequena tabela: gasto | critério. Energia–área; água/telefone/alimentação–empregados; depreciação–máquinas.','["Leia o critério indicado para energia: área ocupada.","Leia separadamente o critério de água, telefone e alimentação: empregados.","Não transfira o critério de um gasto para outro.","Como a afirmação usa empregados para energia, está errada."]'::jsonb),
 (8,'O Departamento de Serviços possui 2 das 10 máquinas da empresa, ou 20%. Aplicando essa participação à depreciação total: 2/10 × R$ 12.000 = R$ 2.400. O cálculo representa a parcela do desgaste atribuída ao departamento, e não uma compra ou pagamento de máquinas. A depreciação é distribuída conforme o critério fornecido no problema.','Parcela do setor = gasto total × quantidade do setor ÷ quantidade total.','["Some as máquinas de todos os departamentos: 10.","Divida as máquinas de Serviços pelo total: 2/10 = 0,20.","Multiplique R$ 12.000 por 0,20.","Resultado: R$ 2.400."]'::jsonb),
 (9,'O custo de produção é formado pela matéria-prima consumida (R$ 9.000), mão de obra direta (R$ 5.000) e custos indiretos de fabricação (R$ 7.230). Somando os três grupos: R$ 9.000 + R$ 5.000 + R$ 7.230 = R$ 21.230. A classificação correta dos itens é essencial: a matéria-prima consumida é custo direto, a mão de obra é custo de produção e os gastos comuns da fábrica formam os custos indiretos.','Organize em três blocos: MP consumida + MOD + CIF. Só depois some.','["Calcule a matéria-prima: 3.000 + 11.000 − 5.000 = R$ 9.000.","Identifique a mão de obra direta: R$ 5.000.","Some os custos indiretos de fabricação: R$ 7.230.","Some os blocos: 9.000 + 5.000 + 7.230 = R$ 21.230."]'::jsonb),
 (10,'Despesas comerciais, administrativas e financeiras não são custos de fabricação. Propaganda é despesa comercial. O custo de produção considera os recursos consumidos para fabricar: matéria-prima, mão de obra direta e custos indiretos de fabricação. Mesmo que essas despesas ocorram durante o mesmo mês em que a fábrica produz, isso não muda sua natureza. O critério é a finalidade do gasto, não apenas a data em que ele aconteceu.','A banca costuma misturar custos e despesas na mesma lista. Classifique cada item pela finalidade antes de somar.','["Marque os gastos ligados diretamente à fabricação.","Separe administração e comercialização como despesas do período.","Separe juros e encargos financeiros como despesas financeiras, salvo regra específica de capitalização.","Some apenas MP consumida, MOD e CIF."]'::jsonb),
 (11,'O enunciado informa que o produto B passa somente por Corte e Costura. Como não utiliza Pintura, não pode receber parcela do custo desse departamento. Atribuir custo a B contrariaria o fluxo produtivo descrito. O rateio deve acompanhar o consumo efetivo dos serviços departamentais descritos no exercício. Se B não passa por Pintura, não há fundamento para atribuir a ele o custo exclusivo dessa etapa.','Produto só recebe custo de departamento pelo qual passa ou que efetivamente o atende, conforme o critério do exercício.','["Leia o roteiro de produção de A e B.","Marque os departamentos utilizados por cada produto.","B utiliza Corte e Costura, mas não Pintura.","Não distribua o custo exclusivo de Pintura ao produto B."]'::jsonb),
 (12,'Os custos unitários resultam da soma dos custos diretos com os custos indiretos atribuídos e, depois, da divisão pela quantidade produzida. A recebe R$ 67.280 no total (R$ 4,49 por unidade); B recebe R$ 52.720 (R$ 5,27 por unidade). Pintura é exclusiva de A.','Não divida o custo total pela produção antes de terminar os rateios. Primeiro atribua todos os departamentos; depois calcule o custo unitário.','["Rateie Administração Geral pela quantidade de funcionários.","Redistribua Almoxarifado pela quantidade de requisições.","Rateie Corte e Costura entre A e B pelo volume produzido.","Atribua Pintura somente a A.","Some custos diretos e indiretos de cada produto e divida pela produção: A = 67.280/15.000 ≈ R$ 4,49; B = 52.720/10.000 = R$ 5,27."]'::jsonb),
 (13,'O Departamento de Serviço ocupa 20 m² de um total de 100 m². Isso corresponde a 20%. Como o critério de energia é área, sua parcela é 20% de R$ 50.000 = R$ 10.000. O percentual é aplicado sobre o gasto total, e não sobre uma parcela escolhida arbitrariamente. A operação pode ser feita como fração (20/100) ou como percentual (20%).','20 de 100 é um quinto, ou 20%. Um quinto de R$ 50.000 é R$ 10.000.','["Divida 20 m² por 100 m²: 0,20.","Converta 0,20 em 20%.","Calcule 20% de R$ 50.000: R$ 10.000.","A afirmação está correta."]'::jsonb),
 (14,'O total do Departamento de Serviço é R$ 32.400, não R$ 30.000. A soma correta inclui energia (R$ 10.000), água/telefone/alimentação (R$ 20.000) e depreciação (R$ 2.400). O valor de R$ 30.000 corresponde apenas à soma das duas primeiras parcelas e deixa a depreciação de fora. Em questões de rateio, confira se todos os gastos apresentados foram considerados.','Confira se somou todas as naturezas de gastos rateadas ao departamento. Não pare após os dois maiores valores.','["Calcule energia: R$ 10.000.","Calcule água, telefone e alimentação: R$ 20.000.","Calcule depreciação: R$ 2.400.","Some: 10.000 + 20.000 + 2.400 = R$ 32.400.","Compare com R$ 30.000: a afirmação está errada."]'::jsonb)
),
rebuilt as (
 select m.id,
        jsonb_agg(
          jsonb_set(
            jsonb_set(
              jsonb_set(x.value,'{why}',to_jsonb(q.why::text),true),
              '{tip}',to_jsonb(q.tip::text),true),
            '{resolution_steps}',q.steps,true
          ) order by x.ordinality
        ) quiz
 from public.study_materials m
 cross join lateral jsonb_array_elements(m.quiz) with ordinality x(value,ordinality)
 join qdata q on q.n=x.ordinality
 where m.contest_name='PC-AC 2026'
   and m.slug='pcac-2026-contabilidade-08-custos-materia-prima-rateio-departamentalizacao'
 group by m.id
)
update public.study_materials m
set quiz=rebuilt.quiz, updated_at=now()
from rebuilt
where m.id=rebuilt.id;
